from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    points = [[grid[r][c] != background for c in range(w)] for r in range(h)]
    out = [row[:] for row in grid]

    for r in range(h):
        cols = [c for c in range(w) if points[r][c]]
        if len(cols) >= 2:
            for c in range(min(cols) + 1, max(cols)):
                if not points[r][c]:
                    out[r][c] = 3

    for c in range(w):
        rows = [r for r in range(h) if points[r][c]]
        if len(rows) >= 2:
            for r in range(min(rows) + 1, max(rows)):
                if not points[r][c]:
                    out[r][c] = 3

    return out
